// Unpack jobs list from scraper response and construct safe AI payload
const response = $input.first().json;
const config = $('User Search Profile & Config').first().json;
const jobs = response.jobs || [];

if (!jobs.length) {
  return [];
}

return jobs.map(job => ({
  json: {
    ...job,
    candidate_skills: config.candidate_skills,
    candidate_exp: config.candidate_experience_years,
    recipient_email: config.recipient_email,
    min_alert_score: config.min_alert_score,
    groq_payload: {
      model: "openai/gpt-oss-20b",
      response_format: { type: "json_object" },
      messages: [
        {
          role: "system",
          content: "You are an expert technical recruiter and career evaluator. Analyze the job posting against candidate profile. Extract recruiter contact info if found, evaluate match score (0-100), required skills, and summary. Return strict JSON with keys: match_score (integer 0-100), match_summary (string), required_skills (array of strings), missing_skills (array of strings), experience_required (string), recruiter_name (string or null), recruiter_email (string or null), recruiter_phone (string or null)."
        },
        {
          role: "user",
          content: `Candidate Skills: ${config.candidate_skills || ''}\nCandidate Experience: ${config.candidate_experience_years || ''} years\n\nJob Title: ${job.title || ''}\nCompany: ${job.company || ''}\nLocation: ${job.location || ''}\nJob Description:\n${(job.description || '').slice(0, 1500)}`
        }
      ]
    }
  }
}));

