// Merge AI assessment results with the original job data
const items = $input.all();
const unpackedItems = $('Unpack Jobs & Attach Profile').all();

const enriched = [];

for (let i = 0; i < items.length; i++) {
  const original = unpackedItems[i] ? unpackedItems[i].json : {};
  const aiResponse = items[i].json;

  let aiData = {};
  try {
    const rawContent = aiResponse?.choices?.[0]?.message?.content;
    if (rawContent) {
      aiData = JSON.parse(rawContent);
    }
  } catch (err) {
    // Fallback if parsing fails
    aiData = {
      match_score: 70,
      match_summary: "Parsed via heuristic match",
      required_skills: original.required_skills || []
    };
  }

  const recEmail = aiData.recruiter_email || original.recruiter_email || null;
  const recName = aiData.recruiter_name || original.recruiter_name || null;
  let draft = null;

  if (recEmail) {
    const skillsStr = (aiData.required_skills && aiData.required_skills.length)
      ? aiData.required_skills.slice(0, 4).join(', ')
      : 'CI/CD, Kubernetes, Terraform, Docker';
    const greeting = recName ? `Dear ${recName},` : 'Dear Hiring Team,';

    draft = {
      subject: `Application: ${original.title} - Johnson Thomas | DevOps & Cloud Engineer`,
      body: `${greeting}\n\nI hope this email finds you well.\n\nI came across the ${original.title} opening at ${original.company} and wanted to reach out directly to express my enthusiastic interest. With 3+ years of hands-on experience as a DevOps & Cloud Engineer, my technical background specializing in ${skillsStr} aligns directly with your engineering requirements.\n\nKey highlights of my background include:\n• Designing and maintaining automated CI/CD pipelines that streamline deployments and reduce manual intervention.\n• Managing containerized microservices on Kubernetes (EKS/GKE) and Docker with Infrastructure-as-Code via Terraform.\n• Optimizing cloud system reliability, proactive telemetry monitoring, and DevSecOps compliance.\n\nI would welcome the opportunity for a brief 10-minute conversation to introduce myself and discuss how my expertise can accelerate ${original.company}'s infrastructure goals. I have also submitted my formal application through your portal.\n\nThank you very much for your time and consideration.\n\nBest regards,\nJohnson Thomas\nDevOps & Cloud Engineer\njohnsonthomas.devops@gmail.com`,
      status: 'drafted'
    };
  }

  enriched.push({
    json: {
      ...original,
      match_score: aiData.match_score ?? (original.match_score || 65),
      match_summary: aiData.match_summary || original.match_summary || "Standard profile match",
      required_skills: (aiData.required_skills && aiData.required_skills.length) ? aiData.required_skills : original.required_skills,
      experience: aiData.experience_required || original.experience || "Not specified",
      recruiter_name: recName,
      recruiter_email: recEmail,
      recruiter_phone: aiData.recruiter_phone || original.recruiter_phone || null,
      email_draft: draft,
      status: "New"
    }
  });
}

// Sort descending by match score
enriched.sort((a, b) => (b.json.match_score || 0) - (a.json.match_score || 0));

return enriched;

// Prepare HTML email digest with summary cards
const allJobs = $('Merge & Rank Jobs by Score').all().map(i => i.json);
const excelBinary = $input.first().binary;
const config = $('User Search Profile & Config').first().json;

const highMatches = allJobs.filter(j => (j.match_score || 0) >= 80);
const topJobs = allJobs.slice(0, 10);

// Build HTML for top jobs
let jobCardsHtml = '';
for (const job of topJobs) {
  const isHigh = (job.match_score || 0) >= 80;
  const badgeBg = isHigh ? '#dcfce7' : '#fef9c3';
  const badgeColor = isHigh ? '#166534' : '#854d0e';
  const skillsBadges = (job.required_skills || []).map(s => 
    `<span style="background:#f1f5f9;color:#334155;font-size:11px;padding:2px 8px;border-radius:4px;margin-right:4px;display:inline-block;">${s}</span>`
  ).join('');

  const recruiterBadge = job.recruiter_email ? `
    <div style="background:#f0fdf4;border:1px dashed #86efac;border-radius:6px;padding:8px 12px;margin:10px 0;font-size:12px;color:#166534;">
      👤 <strong>Recruiter Contact:</strong> ${job.recruiter_name || 'Hiring Team'} &bull; 
      <a href="mailto:${job.recruiter_email}?subject=Application for ${encodeURIComponent(job.title)}" style="color:#166534;font-weight:600;">${job.recruiter_email}</a>
      ${job.recruiter_phone ? ` &bull; 📞 ${job.recruiter_phone}` : ''}
    </div>` : '';

  jobCardsHtml += `
  <div style="background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;margin-bottom:16px;">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;">
      <div>
        <h4 style="font-size:16px;font-weight:600;color:#0f172a;margin:0 0 4px 0;">${job.title}</h4>
        <div style="font-size:13px;color:#475569;">${job.company} &bull; ${job.location}</div>
      </div>
      <span style="background:${badgeBg};color:${badgeColor};font-size:12px;font-weight:700;padding:4px 10px;border-radius:20px;">
        ${job.match_score}% Match
      </span>
    </div>
    <div style="font-size:12px;color:#64748b;margin:8px 0;">
      💼 ${job.experience || 'Experienced'} &bull; 💰 ${job.salary || 'Not Disclosed'} &bull; 🌐 ${job.source_website} &bull; 📅 ${job.date_posted}
    </div>
    ${skillsBadges ? `<div style="margin:8px 0;">${skillsBadges}</div>` : ''}
    ${recruiterBadge}
    <p style="font-size:12px;color:#475569;margin:8px 0;font-style:italic;">"${job.match_summary || ''}"</p>
    <div style="margin-top:12px;">
      <a href="${job.job_url}" target="_blank" style="background:#2563eb;color:#ffffff;padding:7px 14px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;display:inline-block;margin-right:8px;">Apply Now ↗</a>
      ${job.recruiter_email ? `<a href="mailto:${job.recruiter_email}?subject=Application for ${encodeURIComponent(job.title)}" style="background:#f1f5f9;color:#334155;border:1px solid #cbd5e1;padding:7px 14px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;display:inline-block;">Direct Email HR</a>` : ''}
    </div>
  </div>`;
}

const emailHtml = `
<!DOCTYPE html>
<html>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background-color:#f1f5f9;margin:0;padding:20px;">
  <div style="max-width:680px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#1e293b;color:#ffffff;padding:24px;">
      <h2 style="margin:0 0 6px 0;font-size:20px;">🚀 Daily Automated Job Search Digest</h2>
      <p style="margin:0;font-size:13px;color:#94a3b8;">LinkedIn &bull; Indeed &bull; Naukri &bull; Infopark Kochi &bull; Technopark Trivandrum &bull; ATS</p>
    </div>
    <div style="background:#f8fafc;border-bottom:1px solid #e2e8f0;padding:14px 24px;display:flex;">
      <div style="flex:1;text-align:center;"><div style="font-size:18px;font-weight:700;">${allJobs.length}</div><div style="font-size:11px;color:#64748b;">Total Jobs</div></div>
      <div style="flex:1;text-align:center;"><div style="font-size:18px;font-weight:700;color:#16a34a;">${highMatches.length}</div><div style="font-size:11px;color:#64748b;">High Fits (&ge;80%)</div></div>
    </div>
    <div style="padding:24px;">
      <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:12px 16px;margin-bottom:20px;font-size:13px;color:#1e40af;">
        📎 <strong>Attached:</strong> Complete structured Excel spreadsheet (.xlsx) with all discovered postings, links, and recruiter contacts.
      </div>
      <h3 style="font-size:14px;text-transform:uppercase;color:#475569;margin-bottom:14px;">🎯 Top Matches for Your Profile</h3>
      ${jobCardsHtml}
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    recipient_email: config.recipient_email,
    subject: `🚀 Daily Job Digest: ${highMatches.length} High Matches Found (${allJobs.length} New Openings)`,
    html: emailHtml,
    high_matches_count: highMatches.length,
    total_jobs: allJobs.length
  },
  binary: excelBinary
}];
